package piglatin

import "strings"

func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, w := range words {
		words[i] = word(w)
	}
	return strings.Join(words, " ")
}

func word(w string) string {
	if w == "" {
		return w
	}

	// Rule 1: word begins with a vowel, or with "xr" or "yt".
	if isVowel(w[0]) || hasPrefix(w, "xr") || hasPrefix(w, "yt") {
		return w + "ay"
	}

	// Find where the leading consonant cluster ends.
	// Rule 3: a "u" that follows a "q" is part of the cluster ("qu").
	// Rule 4: a "y" after one or more consonants acts as a vowel.
	i := 0
	for i < len(w) {
		c := w[i]
		if c == 'y' {
			break
		}
		if isVowel(c) {
			if c == 'u' && i > 0 && w[i-1] == 'q' {
				i++ // include the "qu" in the cluster
			}
			break
		}
		i++
	}

	return w[i:] + w[:i] + "ay"
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

func hasPrefix(w, prefix string) bool {
	return len(w) >= len(prefix) && w[:len(prefix)] == prefix
}

